// Command pure writes testdata/golden/pure.golden for pbs-gohttp-server: what Go's pure
// functions return for many generated inputs. Run it from the repository root with the Go
// toolchain Prebid ships (go1.26.2):
//
//	GOTOOLCHAIN=go1.26.2 go run ./rust/crates/gohttp-server/testdata/go/pure
//
// Each line is "<function> <quoted input> <quoted output>":
//
//	sniff        http.DetectContentType
//	routerclean  httprouter.CleanPath
//	pathclean    path.Clean
//	canonkey     textproto.CanonicalMIMEHeaderKey
//	mediatype    mime.ParseMediaType, as "<type> <sorted k=quoted-v params> err=<error>"
//	statustext   http.StatusText (the input is the decimal code)
package main

import (
	"encoding/binary"
	"flag"
	"fmt"
	"math/rand"
	"mime"
	"net/http"
	"net/textproto"
	"os"
	"path"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"

	"github.com/julienschmidt/httprouter"
)

func main() {
	out := flag.String("out", defaultOut(), "golden file to write")
	flag.Parse()
	var b strings.Builder
	b.WriteString("# Generated by testdata/go/pure (" + runtime.Version() + "). Do not edit.\n")
	line := func(fn, in, got string) {
		fmt.Fprintf(&b, "%s %s %s\n", fn, strconv.Quote(in), strconv.Quote(got))
	}
	for _, in := range sniffInputs() {
		line("sniff", in, http.DetectContentType([]byte(in)))
	}
	for _, in := range pathInputs() {
		line("routerclean", in, httprouter.CleanPath(in))
		line("pathclean", in, path.Clean(in))
	}
	for _, in := range keyInputs() {
		line("canonkey", in, textproto.CanonicalMIMEHeaderKey(in))
	}
	for _, in := range mediaTypeInputs() {
		line("mediatype", in, mediaType(in))
	}
	for code := 0; code <= 1000; code++ {
		line("statustext", strconv.Itoa(code), http.StatusText(code))
	}
	if err := os.WriteFile(*out, []byte(b.String()), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func defaultOut() string {
	_, file, _, _ := runtime.Caller(0)
	return filepath.Join(filepath.Dir(file), "..", "..", "golden", "pure.golden")
}

// signatures are the patterns of Go's sniffSignatures table, with the masked bytes zero.
var signatures = []string{
	"<!DOCTYPE HTML", "<HTML", "<HEAD", "<SCRIPT", "<IFRAME", "<H1", "<DIV", "<FONT", "<TABLE",
	"<A", "<STYLE", "<TITLE", "<B", "<BODY", "<BR", "<P", "<!--", "<?xml", "%PDF-",
	"%!PS-Adobe-", "\xFE\xFF\x00\x00", "\xFF\xFE\x00\x00", "\xEF\xBB\xBF\x00", "\x00\x00\x01\x00",
	"\x00\x00\x02\x00", "BM", "GIF87a", "GIF89a", "RIFF\x00\x00\x00\x00WEBPVP",
	"\x89PNG\x0D\x0A\x1A\x0A", "\xFF\xD8\xFF", "FORM\x00\x00\x00\x00AIFF", "ID3", "OggS\x00",
	"MThd\x00\x00\x00\x06", "RIFF\x00\x00\x00\x00AVI ", "RIFF\x00\x00\x00\x00WAVE",
	"\x1A\x45\xDF\xA3", strings.Repeat("\x00", 34) + "LP", "\x00\x01\x00\x00", "OTTO", "ttcf",
	"wOFF", "wOF2", "\x1F\x8B\x08", "PK\x03\x04", "Rar!\x1A\x07\x00", "Rar!\x1A\x07\x01\x00",
	"\x00\x61\x73\x6D",
}

// sniffInputs combines every signature with leading bytes, trailing bytes and changes, and
// adds MP4 boxes, every single byte, the 512-byte limit and random inputs.
func sniffInputs() []string {
	var in []string
	leads := []string{"", " ", "\t\n\x0c\r ", "\x0b", "\x00"}
	tails := []string{"", " ", ">", "x", "\x00", " \x01", "\n", "\x1b"}
	for _, sig := range signatures {
		variants := []string{sig, strings.ToLower(sig), sig[:len(sig)-1]}
		if len(sig) >= 8 {
			variants = append(variants, sig[:4]+"abcd"+sig[8:], sig[:4]+"\xff\xff\xff\xff"+sig[8:])
		}
		for _, v := range variants {
			for _, lead := range leads {
				for _, tail := range tails {
					in = append(in, lead+v+tail)
				}
			}
		}
	}
	for _, size := range []uint32{0, 4, 7, 8, 12, 13, 16, 20, 24, 28, 32, 1 << 31} {
		for _, n := range []int{11, 12, 16, 24, 32, 36} {
			for _, at := range []int{8, 12, 16, 20, 28} {
				b := make([]byte, n)
				binary.BigEndian.PutUint32(b, size)
				copy(b[4:], "ftyp")
				if at+3 <= n {
					copy(b[at:], "mp4")
				}
				in = append(in, string(b))
			}
		}
	}
	for b := 0; b < 256; b++ {
		c := string([]byte{byte(b)})
		in = append(in, c, "a"+c, " "+c+"a", c+"<html>", "<html"+c, "<?xml"+c)
	}
	for _, n := range []int{510, 511, 512, 513} {
		in = append(in, strings.Repeat("a", n)+"\x00", strings.Repeat(" ", n)+"<html>")
	}
	alphabet := []byte("<>!-?xmlHhTtMmLlPpDdFfBbRrIiSs%PDF \t\n\r\x0c\x0b\x00\x01\x1a\x1b\x1f\x7f\x80\xbf\xef\xfe\xff")
	rnd := rand.New(rand.NewSource(1))
	for i := 0; i < 3000; i++ {
		b := make([]byte, rnd.Intn(24))
		for j := range b {
			b[j] = alphabet[rnd.Intn(len(alphabet))]
		}
		in = append(in, string(b))
	}
	return in
}

// pathInputs are every path of up to seven bytes over "/", "." and "a", and random longer
// paths of segments, dots, escapes and slashes.
func pathInputs() []string {
	in := []string{""}
	level := []string{""}
	for n := 1; n <= 7; n++ {
		var next []string
		for _, p := range level {
			for _, c := range []string{"/", ".", "a"} {
				next = append(next, p+c)
			}
		}
		in = append(in, next...)
		level = next
	}
	parts := []string{"/", "/", "/", ".", "..", "a", "bc", "//", "%2e", "~", "é", "..."}
	rnd := rand.New(rand.NewSource(2))
	for i := 0; i < 1500; i++ {
		var b strings.Builder
		for j := rnd.Intn(12); j >= 0; j-- {
			b.WriteString(parts[rnd.Intn(len(parts))])
		}
		in = append(in, b.String())
	}
	return in
}

// keyInputs are every key of up to four bytes over "a", "B", "-", "_", " " and "1", and some
// real and invalid keys.
func keyInputs() []string {
	in := []string{""}
	level := []string{""}
	for n := 1; n <= 4; n++ {
		var next []string
		for _, k := range level {
			for _, c := range []string{"a", "B", "-", "_", " ", "1"} {
				next = append(next, k+c)
			}
		}
		in = append(in, next...)
		level = next
	}
	return append(in,
		"content-type", "CONTENT-TYPE", "x-forwarded-for", "www-authenticate", "Www-Authenticate",
		"sec-gpc", "dnt", "x_under_score", "foo bar", "é", "a\x00b", "a\x7fb", "a:b", "a\tb",
		"-a-", "--", "a--b", "1a", "a1b-c2", "x-UPPER-lower", "a.b", "a~b", "a!#$%&'*+.^`|~b",
	)
}

// mediaTypeInputs combine media types with parameter lists.
func mediaTypeInputs() []string {
	bases := []string{
		"text/html", "TEXT/HTML", " text/html ", "text/", "/html", "text", "", "text/html/x",
		"text/ html", "application/x-www-form-urlencoded", "multipart/form-data", "a@b/c",
		"text/html x", "Application/JSON", "\ttext/plain\t", "text/plain;",
	}
	params := []string{
		"", ";", " ; ", "; charset=utf-8", ";charset=UTF-8", "; charset=\"utf-8\"", "; charset=",
		"; =x", "; a=1; a=1", "; a=1; a=2", "; a=1;", "; a=1 ; b=2", "; a=\"x\\\"y\"",
		"; a=\"unterminated", "; a=\"q\\\\w\"", "; A=1", "; a = 1", "; a=1 junk", ";;",
		"; a=\"\"", "; a=\"x\r\ny\"", "; a=\"\\q\"", "; a=1; A=2", "; a=é", "; é=1",
		"; a=\"é\"", ";\u00a0a=1", "; a=1;\u3000", "; a=@", "; a=\"@\"",
	}
	var in []string
	for _, b := range bases {
		for _, p := range params {
			in = append(in, b+p)
		}
	}
	return in
}

func mediaType(v string) string {
	mt, params, err := mime.ParseMediaType(v)
	keys := make([]string, 0, len(params))
	for k := range params {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	b.WriteString(mt)
	for _, k := range keys {
		fmt.Fprintf(&b, " %s=%s", k, strconv.Quote(params[k]))
	}
	fmt.Fprintf(&b, " err=%v", err)
	return b.String()
}
